// Description: Class to post Customer MDF as Free Text Invoice
public abstract class METCustomerMDFPosting_FreeTextInvoice extends METCustomerMDFPosting
{
    CustInvoiceTable custInvoiceTable;

}

Method.Source:
/// <summary>
/// Abstract method to get the query for fetching METCustomerMDFConsolidationTable records
/// </summary>
/// <returns>Query</returns>
abstract Query getQuery()
{
}

/// <summary>
/// Create a consolidation posting line in CustInvoiceLine and CustInvoiceTable
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <returns>RecId</returns>
RecId createConsolidationPostingLine(METCustomerMDFConsolidationTable _consolidationPosting)
{
    if(!custInvoiceTable)
    {
        custInvoiceTable =  this.createCustInvoiceTableHeader(_consolidationPosting);
    }

    return this.createCustInvoiceLine(_consolidationPosting);
}

/// <summary>
/// Auto post the created free text invoice
/// </summary>
/// <returns>boolean</returns>
boolean autoPost()
{
    return true;
}

/// <summary>
/// Post the created free text invoice
/// </summary>
void post()
{
    new CustPostInvoice(custInvoiceTable).run();
}

/// <summary>
/// Create the header for CustInvoiceTable
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <returns>CustInvoiceTable</returns>
CustInvoiceTable createCustInvoiceTableHeader(METCustomerMDFConsolidationTable _consolidationPosting)
{
    CustInvoiceTable custInvoiceTableInsert;
    CustTable custTable;

    custInvoiceTableInsert.initValue();

    custTable = CustTable::find(_consolidationPosting.CustAccount);
    custInvoiceTableInsert.initFromCustTable(custTable);

    if(custInvoiceTableInsert.validateWrite())
    {
        custInvoiceTableInsert.insert();
    }

    return custInvoiceTableInsert;
}

/// <summary>
/// Create a line for CustInvoiceLine
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <returns>RecId</returns>
RecId createCustInvoiceLine(METCustomerMDFConsolidationTable _consolidationPosting)
{
    CustInvoiceLine custInvoiceLine;
    MetCustomerMdfSetupTable customerMDFSetupTable;

    customerMDFSetupTable = MetCustomerMdfSetupTable::findRecId(_consolidationPosting.CustomerMDFSetupTable);

    custInvoiceLine.clear();
    custInvoiceLine.initValue();
    custInvoiceLine.LineNum = CustInvoiceLine::lastLineNum_W(custInvoiceLine.ParentRecId);
    custInvoiceLine.ParentRecId = custInvoiceTable.RecId;
    custInvoiceLine.initFromCustInvoiceTable(custInvoiceTable);
    custInvoiceLine.Description = customerMDFSetupTable.Description;
    custInvoiceLine.TaxItemGroup = customerMDFSetupTable.GST;
    custInvoiceLine.UnitPrice = _consolidationPosting.MDF;
    //todo: set appropriate ledger dimension
    custInvoiceLine.LedgerDimension = 5637173827;

    if(custInvoiceLine.validateWrite())
    {
        custInvoiceLine.insert();
    }

    return custInvoiceLine.RecId;
}

/// <summary>
/// Get the posting table id for CustInvoiceTable
/// </summary>
/// <returns>RefTableId</returns>
RefTableId getPostingTableId()
{
    return tableNum(CustInvoiceTable); 
}

/// <summary>
/// Abstract method to update the METCustomerMDFConsolidationTable with the posting reference
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <param name = "_postingRefRecId">RefRecId</param>
abstract void updateCustomerMDFConsolidationTable(METCustomerMDFConsolidationTable _consolidationPosting, RefRecId _postingRefRecId)
{
}
